        if (sl) { sl.max = n - 1; sl.value = n - 1; }
        var pb = document.getElementById('ir-anim-play');
        if (pb) { pb.disabled = false; pb.title = 'Play/Pause'; }
        updateAnimCounter();
        updateFrameOverlay();
