    var _RT_BUNDLE_VERSION = 'rt-v12';   // fallback; _loadBundleVersion() may update
    var _GCS_BUNDLE_BASE = _RT_BUNDLE_ROOT + '/' + _RT_BUNDLE_VERSION + '/bundles';
